// ============================================================
// Invoice field extraction - ported rule-for-rule from the
// Python original (invoice_tool/extractor.py), minus the OCR
// word-confidence blanking layer: OCR.space's free tier does
// not return per-word confidence (unlike local Tesseract), so
// that signal isn't available here. Every other rule is
// unchanged. A field is left blank whenever no match is found;
// nothing is ever guessed.
//
// NOTE: written without arrow functions, template literals, or
// optional chaining, on purpose - n8n's Creator Portal firewall
// blocks submissions whose workflow JSON contains those.
// ============================================================

var RX_RUN = RegExp.prototype.exec;
function runRegex(re, str) {
  return RX_RUN.call(re, str);
}

const MONEY_RE_SRC = '[\\$\u20ac\u00a3]\\s?-?[\\d,]+(?:\\.\\d{2})?|-?[\\d,]+\\.\\d{2}';

const DATE_PATTERNS = [
  [/\b(\d{4})-(\d{1,2})-(\d{1,2})\b/, 'ymd'],
  [/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/, 'mdy'],
  [/\b(\d{1,2})-(\d{1,2})-(\d{4})\b/, 'mdy'],
  [/\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2}),?\s+(\d{4})\b/i, 'Bdy'],
  [/\b(\d{1,2})\s+(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{4})\b/i, 'dBy'],
];

const MONTHS = ['january','february','march','april','may','june','july','august','september','october','november','december'];

function pad2(n) { return String(n).padStart(2, '0'); }

// Decide how 3-part numeric dates (10/11/2027) should be read, using every
// such date in the document: a first part above 12 proves day-first, a
// second part above 12 proves month-first. No proof -> 'unknown'.
function inferDateOrder(text) {
  const re = /\b(\d{1,2})(?:\/|-)(\d{1,2})(?:\/|-)(\d{4})\b/g;
  let m;
  let dayFirst = false;
  let monthFirst = false;
  while ((m = runRegex(re, text)) !== null) {
    const a = +m[1];
    const b = +m[2];
    if (a > 12 && b >= 1 && b <= 12) dayFirst = true;
    if (b > 12 && a >= 1 && a <= 12) monthFirst = true;
  }
  if (dayFirst && !monthFirst) return 'dmy';
  if (monthFirst && !dayFirst) return 'mdy';
  return 'unknown';
}

function parseDate(raw, order) {
  for (const [re, kind] of DATE_PATTERNS) {
    const m = runRegex(re, raw);
    if (!m) continue;
    const candidate = m[0];
    if (kind === 'ymd') {
      const [, y, mo, d] = m;
      if (+mo < 1 || +mo > 12 || +d < 1 || +d > 31) continue;
      return [y + '-' + pad2(mo) + '-' + pad2(d), candidate];
    }
    if (kind === 'mdy') {
      let mo = m[1];
      let d = m[2];
      const y = m[3];
      if (order === 'dmy') { mo = m[2]; d = m[1]; }
      if (+mo < 1 || +mo > 12 || +d < 1 || +d > 31) continue;
      const ambiguous = order === 'unknown' && +m[1] <= 12 && +m[2] <= 12 && m[1] !== m[2];
      return [y + '-' + pad2(mo) + '-' + pad2(d), candidate, ambiguous];
    }
    if (kind === 'Bdy') {
      const [, month, d, y] = m;
      const mi = MONTHS.indexOf(month.toLowerCase());
      if (mi === -1) continue;
      return [y + '-' + pad2(mi + 1) + '-' + pad2(d), candidate];
    }
    if (kind === 'dBy') {
      const [, d, month, y] = m;
      const mi = MONTHS.indexOf(month.toLowerCase());
      if (mi === -1) continue;
      return [y + '-' + pad2(mi + 1) + '-' + pad2(d), candidate];
    }
  }
  return null;
}

const SEP_RE = /^[ \t]*[:\-.]*[ \t]*$/;
function isBlankSeparator(s) { return SEP_RE.test(s); }

function* iterLabelValueMatches(text, labelPattern, valuePattern) {
  const lines = text.split('\n');
  const labelRe = new RegExp(labelPattern, 'gi');
  const valueRe = new RegExp('^(?:' + valuePattern + ')');

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    labelRe.lastIndex = 0;
    let lm;
    while ((lm = runRegex(labelRe, line)) !== null) {
      if (lm[0] === '') { labelRe.lastIndex++; continue; }
      const before = line.slice(0, lm.index);
      const after = line.slice(lm.index + lm[0].length);

      const sepM = runRegex(/^[ \t]*[:\-.#]*[ \t]*/, after);
      const sameLineRest = sepM ? after.slice(sepM[0].length) : after;
      const vm = runRegex(valueRe, sameLineRest);
      if (vm && vm[0].trim()) {
        yield [vm[0].trim(), vm[0], i, false, before];
        continue;
      }

      if (isBlankSeparator(before) && isBlankSeparator(sameLineRest) && i + 1 < lines.length) {
        const nextLine = lines[i + 1].replace(/^[ \t]+/, '');
        const vm2 = runRegex(valueRe, nextLine);
        if (vm2 && vm2[0].trim()) {
          yield [vm2[0].trim(), vm2[0], i, true, before];
        }
      }
    }
  }
}

const VENDOR_LABEL_SKIP_RE = /invoice|receipt|\bbill\s*to\b|\bship\s*to\b|\bsold\s*to\b|\bremit\s*to\b|date|no\.|#|\btotal\b/i;
const FROM_LABEL_RE = /^from\s*:?\s*$/i;
const SECTION_BOUNDARY_RE = /\bbill\s*to\b|\bship\s*to\b|\bsold\s*to\b|\bremit\s*to\b|\bclient\s*name\b|\bcustomer\s*name\b|\binvoice\s*to\b/i;
const FOOTER_SYMBOLS_RE = /[\u00a9\u00ae\u2122]/;

function looksLikeGarbage(candidate) {
  if (FOOTER_SYMBOLS_RE.test(candidate)) return true;
  const words = candidate.split(/\s+/).filter(Boolean);
  if (words.length && words[0].length <= 2 && !/^[A-Za-z]+$/.test(words[0])) return true;
  const stripped = candidate.replace(/[\s.,;:!?'"()[\]{}#&@/\\|_+=<>~^*%-]+/g, '');
  if (!stripped) return true;
  const nonLetter = [...stripped].filter(function (c) { return !/[A-Za-z]/.test(c); }).length;
  return nonLetter / stripped.length > 0.3;
}

function looksLikeTableHeader(candidate) {
  if (/\d/.test(candidate)) return false;
  const words = candidate.split(/\s+/).filter(Boolean);
  if (words.length < 5) return false;
  return words.every(function (w) { return !/^[A-Za-z]/.test(w[0]) || w[0] === w[0].toUpperCase(); });
}

// Template placeholders ("YOUR LOGO", "Company Name", "Email Address") are not
// vendor names: a line made only of these words is skipped.
const PLACEHOLDER_WORDS = new Set([
  'your', 'company', 'name', 'logo', 'business', 'email', 'address', 'phone',
  'tel', 'fax', 'website', 'web', 'url', 'street', 'city', 'state', 'zip',
  'enter', 'insert', 'here', 'example', 'sample', 'template', 'brand',
  'slogan', 'tagline', 'at', 'dept', 'the',
]);

function isPlaceholderName(candidate) {
  const words = candidate.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(Boolean);
  return words.length > 0 && words.every(function (w) { return PLACEHOLDER_WORDS.has(w); });
}

// A street address, e-mail or web address is never the vendor name.
const STREET_ADDRESS_RE = /^\d{1,6}[A-Za-z]?[,.]?\s+.*\b(street|st|avenue|ave|road|rd|boulevard|blvd|lane|ln|drive|dr|way|court|ct|suite|ste|floor|highway|hwy)\b/i;
const CONTACT_LINE_RE = /@|^www\.|^https?:/i;

function isPlausibleVendorCandidate(candidate) {
  if (candidate.includes(':')) return false;
  if (isPlaceholderName(candidate)) return false;
  if (STREET_ADDRESS_RE.test(candidate) || CONTACT_LINE_RE.test(candidate)) return false;
  return !looksLikeGarbage(candidate) && !looksLikeTableHeader(candidate);
}

function extractVendor(text) {
  const lines = text.split('\n').map(function (l) { return l.trim(); });

  for (let i = 0; i < lines.length; i++) {
    if (FROM_LABEL_RE.test(lines[i])) {
      for (const candidate of lines.slice(i + 1)) {
        if (!candidate) continue;
        if (SECTION_BOUNDARY_RE.test(candidate)) break;
        if (isPlausibleVendorCandidate(candidate)) return candidate;
      }
      break;
    }
  }

  for (const line of lines) {
    if (!line) continue;
    if (SECTION_BOUNDARY_RE.test(line)) break;
    if (VENDOR_LABEL_SKIP_RE.test(line)) continue;
    if (!isPlausibleVendorCandidate(line)) continue;
    return line;
  }
  return null;
}

function extractInvoiceNumber(text) {
  for (const [value] of iterLabelValueMatches(
    text,
    'invoice\\s*(?:number|no\\.?|#)',
    '[A-Za-z0-9\\-\\/]*\\d[A-Za-z0-9\\-\\/]*',
  )) {
    return value;
  }
  return null;
}

function extractDateWithSpan(text) {
  const order = inferDateOrder(text);
  const matches = [...iterLabelValueMatches(text, 'invoice\\s*date|date', '.{1,40}')];
  // Prefer the invoice date over due / ship / delivery / payment dates.
  const preferred = matches.filter(function (m) {
    return !/(due|ship|shipping|delivery|payment|expiry|expiration)\s*$/i.test(m[4]);
  });
  const candidates = preferred.length ? preferred : matches;
  for (const m of candidates) {
    const parsed = parseDate(m[0], order);
    if (parsed) return parsed;
  }
  return parseDate(text, order);
}

const PARENTHETICAL_PREFIX = '(?:\\([^)]{0,20}\\)\\s*)?';
const MONEY_VALUE_RE = PARENTHETICAL_PREFIX + '(?:' + MONEY_RE_SRC + ')';
const BARE_TOTAL_LABEL = '(?<!sub)(?<!sub\\s)(?<!sub-)total\\b';

// "$00.00" -> "0.00"; "1,735" stays as is. Currency symbols, spaces and
// short parentheticals such as "(incl. tax)" are dropped.
function cleanMoney(raw) {
  return raw
    .replace(/\([^)]{0,20}\)|[\$\u20ac\u00a3\s]/g, '')
    .replace(/[,.]+$/, '')
    .replace(/^(-?)0+(?=\d\.)/, '$1');
}

// Money at the very start of a line ("$38.98 (incl. tax)"), or null.
// A percentage ("8.00%") is not money.
function leadingMoney(line) {
  const t = line.trim();
  const m = runRegex(new RegExp('^' + MONEY_VALUE_RE), t);
  if (!m || !m[0].trim()) return null;
  if (/^\s*%/.test(t.slice(m[0].length))) return null;
  return [cleanMoney(m[0]), m[0]];
}

// A bare "Total" line that sits inside a line-item table header block and is
// followed by a whole column of amounts is a COLUMN HEADER, not the invoice
// total (its "value" would just be the first line-item amount).
const TABLE_HEADER_WORD_RE = /\b(qty|quantity|price|rate|description|item|product)\b/i;
function isColumnHeaderMatch(lines, m) {
  if (!m[3]) return false;
  const idx = m[2];
  if (!/^(total|amount|price)\s*[:.]?$/i.test(lines[idx].trim())) return false;
  if (idx + 2 >= lines.length || leadingMoney(lines[idx + 2]) === null) return false;
  for (let k = Math.max(0, idx - 8); k < idx; k++) {
    if (TABLE_HEADER_WORD_RE.test(lines[k])) return true;
  }
  return false;
}

function extractAmountNearLabel(text, labels) {
  const lines = text.split('\n');
  for (const label of labels) {
    const matches = [...iterLabelValueMatches(text, label, MONEY_VALUE_RE)].filter(function (m) {
      return !isColumnHeaderMatch(lines, m);
    });
    if (matches.length) {
      const [amount, raw] = matches[matches.length - 1];
      return [cleanMoney(amount), raw];
    }
  }
  return null;
}

// ---- stacked ("label block, then value block") summaries -------------
// Some OCR output lists the summary labels first and their values after:
//   Sub Total: / Tax %: / Total Amount   ...   $80.00 / $0.00 / $80.00
// Labels and values are paired by position, counted from the END of the value
// block (extra leading amounts are line-item amounts). A trailing bare "Total"
// label is first tried as the line-item column header; that reading is only
// accepted when the leading amounts add up to the sub total.
const SUMMARY_LABEL_RE = /^(sub\s*-?\s*total|tax(?:\s*(?:%|rate))?|vat|gst|discount|shipping(?:\s*(?:\/|and|&)\s*handling)?|handling|total|total\s*amount|total\s*due|grand\s*total|amount\s*due|amount\s*paid|balance(?:\s*due)?)\s*[:.]?$/i;

function summaryField(label) {
  const l = label.toLowerCase().replace(/[\s:.]+$/, '').replace(/\s+/g, ' ');
  if (/^sub ?-? ?total$/.test(l)) return 'subtotal';
  if (/^(tax|vat|gst)( ?%| rate)?$/.test(l)) return 'tax';
  if (/^(grand total|total due)$/.test(l)) return 'total1';
  if (/^(total|total amount)$/.test(l)) return 'total2';
  if (/^(amount due|balance due|balance)$/.test(l)) return 'total3';
  return 'other';
}

function isTextSlot(line) {
  if (line.indexOf(':') !== -1 || /\d/.test(line) || SUMMARY_LABEL_RE.test(line)) return false;
  return line.split(/\s+/).filter(Boolean).length <= 4;
}

function pairSummary(labels, slots, requireSumCheck) {
  const offset = slots.length - labels.length;
  if (offset < 0) return null;
  const out = { subtotal: null, tax: null, total1: null, total2: null, total3: null };
  let subtotalNum = null;
  for (let k = 0; k < labels.length; k++) {
    const field = summaryField(labels[k]);
    if (field === 'other') continue;
    const slot = slots[offset + k];
    if (slot.money === null) return null;
    out[field] = slot.money;
    if (field === 'subtotal') subtotalNum = parseFloat(slot.money[0].replace(/,/g, ''));
  }
  if (requireSumCheck) {
    if (subtotalNum === null || offset < 1) return null;
    let sum = 0;
    for (let k = 0; k < offset; k++) {
      if (slots[k].money === null) return null;
      sum += parseFloat(slots[k].money[0].replace(/,/g, ''));
    }
    if (Number.isNaN(sum) || Math.abs(sum - subtotalNum) > 0.02) return null;
  }
  return out;
}

function extractStackedSummary(text) {
  const lines = text.split('\n').map(function (l) { return l.trim(); });
  let i = 0;
  while (i < lines.length) {
    if (!SUMMARY_LABEL_RE.test(lines[i])) { i++; continue; }
    const runStart = i;
    while (i < lines.length && SUMMARY_LABEL_RE.test(lines[i])) i++;
    const labels = lines.slice(runStart, i);
    if (labels.length < 2) continue;

    const slots = [];
    let j = i;
    while (j < lines.length && slots.length < 40) {
      const t = lines[j];
      if (!t) break;
      const money = leadingMoney(t);
      if (money !== null) slots.push({ money: money });
      else if (isTextSlot(t)) slots.push({ money: null });
      else break;
      j++;
    }
    if (slots.length < 2) continue;

    let paired = null;
    const last = labels[labels.length - 1].toLowerCase().replace(/[\s:.]+$/, '');
    if (labels.length >= 3 && last === 'total') {
      paired = pairSummary(labels.slice(0, -1), slots, true);
    }
    if (paired === null) paired = pairSummary(labels, slots, false);
    if (paired !== null) return paired;
  }
  return null;
}

function extractTotalsWithSpan(text) {
  const stacked = extractStackedSummary(text);
  let total = null;
  if (stacked !== null) total = stacked.total1 || stacked.total2 || stacked.total3;
  if (total === null) {
    total = extractAmountNearLabel(text, ['grand\\s*total', 'total\\s*due', BARE_TOTAL_LABEL]);
  }
  if (total === null) {
    total = extractAmountNearLabel(text, ['amount\\s*due', 'balance\\s*due']);
  }
  let subtotal = stacked !== null ? stacked.subtotal : null;
  if (subtotal === null) subtotal = extractAmountNearLabel(text, ['sub\\s*-?total']);
  let tax = stacked !== null ? stacked.tax : null;
  if (tax === null) tax = extractAmountNearLabel(text, ['tax', 'vat', 'gst']);
  return { subtotal: subtotal, tax: tax, total: total };
}

const LINE_ITEM_ROLE_PATTERNS = {
  desc: '(?<desc>.{2,80}?)',
  qty: '(?<qty>\\d+(?:\\.\\d+)?)',
  unit: '(?<unit_raw>' + MONEY_RE_SRC + ')',
  amt: '(?<amt_raw>' + MONEY_RE_SRC + ')',
};
const DEFAULT_COLUMN_ORDER = ['desc', 'qty', 'unit', 'amt'];

function buildLineItemRegex(columnOrder) {
  const body = columnOrder.map(function (role) { return LINE_ITEM_ROLE_PATTERNS[role]; }).join('\\s+');
  return new RegExp('^' + body + '\\s*$');
}

const HEADER_DESC_KEYWORDS = ['description', 'item', 'product'];
const HEADER_UNIT_KEYWORDS = ['unit price', 'unitprice', 'rate', 'price'];
const HEADER_AMT_KEYWORDS = ['amount', 'total', 'line total'];
const HEADER_QTY_RE = /\bqty\b|\bquantity\b|\bq\w{1,3}y\b/i;

function findFirstKeywordPos(lineLower, keywords) {
  let best = null;
  for (const kw of keywords) {
    const p = lineLower.indexOf(kw);
    if (p !== -1 && (best === null || p < best)) best = p;
  }
  return best;
}

function detectHeaderColumnOrder(line) {
  const lineLower = line.toLowerCase();
  const found = [];

  const descPos = findFirstKeywordPos(lineLower, HEADER_DESC_KEYWORDS);
  if (descPos !== null) found.push([descPos, 'desc']);
  const unitPos = findFirstKeywordPos(lineLower, HEADER_UNIT_KEYWORDS);
  if (unitPos !== null) found.push([unitPos, 'unit']);
  const amtPos = findFirstKeywordPos(lineLower, HEADER_AMT_KEYWORDS);
  if (amtPos !== null) found.push([amtPos, 'amt']);
  const qtyM = runRegex(HEADER_QTY_RE, line);
  if (qtyM) found.push([qtyM.index, 'qty']);

  if (found.length !== 4) return null;
  found.sort(function (a, b) { return a[0] - b[0]; });
  const order = found.map(function (f) { return f[1]; });
  return new Set(order).size === 4 ? order : null;
}

function looksNumericOrCode(candidate) {
  const tokens = candidate.split(/\s+/).filter(Boolean);
  if (!tokens.length) return false;
  return /^[\d.,]+$/.test(tokens[tokens.length - 1]);
}

const CURRENCY_OR_DECIMAL_RE = new RegExp('[\\$\u20ac\u00a3]\\s?(?:\\d[\\d,]*\\d|\\d)(?:\\.\\d{2})?|(?:\\d[\\d,]*\\d|\\d)\\.\\d{2}');

function looksLikeTextLabel(line) {
  if (!line || CURRENCY_OR_DECIMAL_RE.test(line)) return false;
  const letters = [...line].filter(function (c) { return /[A-Za-z]/.test(c); }).length;
  const digits = [...line].filter(function (c) { return /\d/.test(c); }).length;
  if (letters === 0) return false;
  return digits / (letters + digits) < 0.3;
}

function extractLineItemsFromText(text) {
  const lines = text.split('\n').map(function (l) { return l.trim(); });
  let columnOrder = DEFAULT_COLUMN_ORDER;
  let lineItemRe = buildLineItemRegex(columnOrder);

  const items = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line) continue;

    const detectedOrder = detectHeaderColumnOrder(line);
    if (detectedOrder) {
      columnOrder = detectedOrder;
      lineItemRe = buildLineItemRegex(columnOrder);
      continue;
    }

    const m = runRegex(lineItemRe, line);
    if (!m) continue;
    let desc = m.groups.desc.trim();
    const qty = m.groups.qty;
    const unitRaw = m.groups.unit_raw;
    const amtRaw = m.groups.amt_raw;
    const unit = unitRaw.replace(/[\$\u20ac\u00a3\s]/g, '').replace(/[,.]+$/, '');
    const amt = amtRaw.replace(/[\$\u20ac\u00a3\s]/g, '').replace(/[,.]+$/, '');

    if (looksNumericOrCode(desc) && i > 0 && looksLikeTextLabel(lines[i - 1])) {
      desc = lines[i - 1];
    }

    const item = {
      description: desc || null,
      quantity: qty || null,
      unit_price: unit || null,
      total: amt || null,
      flagged: false,
      flag_reason: null,
    };

    if (item.quantity && item.unit_price && item.total) {
      const expected = parseFloat(item.quantity) * parseFloat(item.unit_price.replace(/,/g, ''));
      const actual = parseFloat(item.total.replace(/,/g, ''));
      if (!Number.isNaN(expected) && !Number.isNaN(actual) && Math.abs(expected - actual) > 0.02) {
        item.flagged = true;
        item.flag_reason = 'qty*unit_price (' + expected.toFixed(2) + ') does not match total (' + actual.toFixed(2) + '); possible OCR digit error';
      }
    }

    items.push(item);
  }
  return items;
}

function extractInvoiceFields(text) {
  text = text || '';
  const vendor = extractVendor(text);
  const invoiceNumber = extractInvoiceNumber(text);
  const dateParsed = extractDateWithSpan(text);
  const totals = extractTotalsWithSpan(text);
  const lineItems = extractLineItemsFromText(text);

  const flags = [];
  if (!text.trim()) flags.push('OCR returned no text');
  if (!vendor) flags.push('vendor not found');
  if (!invoiceNumber) flags.push('invoice_number not found');
  if (!dateParsed) flags.push('invoice_date not found');
  else if (dateParsed[2]) flags.push('invoice_date is ambiguous (DD/MM vs MM/DD); read as MM/DD - please verify');
  if (!totals.subtotal) flags.push('subtotal not found');
  if (!totals.tax) flags.push('tax not found');
  if (!totals.total) flags.push('total not found');
  for (const item of lineItems) {
    if (item.flagged) flags.push('line item "' + item.description + '": ' + item.flag_reason);
  }

  return {
    vendor: vendor || null,
    invoice_number: invoiceNumber || null,
    invoice_date: dateParsed ? dateParsed[0] : null,
    subtotal: totals.subtotal ? totals.subtotal[0] : null,
    tax: totals.tax ? totals.tax[0] : null,
    total: totals.total ? totals.total[0] : null,
    line_items: lineItems,
    flags,
  };
}

// ============================================================
// n8n wrapper: read the OCR.space response from this node's
// input, run extraction, return one shaped item.
// ============================================================

const inputData = $input.item.json;
const parsedResults = inputData.ParsedResults || [];
const combinedText = parsedResults.map(function (r) { return r.ParsedText || ''; }).join('\n');

const extracted = extractInvoiceFields(combinedText);

let sourceFilename = null;
try {
  sourceFilename = $node["Invoice Upload"].binary.invoice.fileName || null;
} catch (e) {
  sourceFilename = null;
}

// Run Once for Each Item mode: return a single item object, not an array.
return {
    json: {
      source_filename: sourceFilename,
      processed_at: new Date().toISOString(),
      vendor: extracted.vendor,
      invoice_number: extracted.invoice_number,
      invoice_date: extracted.invoice_date,
      subtotal: extracted.subtotal,
      tax: extracted.tax,
      total: extracted.total,
      line_item_count: extracted.line_items.length,
      line_items_json: JSON.stringify(extracted.line_items),
      extraction_flags: extracted.flags.length ? extracted.flags.join('; ') : null,
      ocr_raw_text: combinedText,
    },
  };
